import{_ as s,o as a,c as n,a as l}from"./app.DkoUFz-u.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"backend/observability/logging/collection.md","filePath":"backend/observability/logging/collection.md"}'),e={name:"backend/observability/logging/collection.md"};function i(o,t,r,h,p,g){return a(),n("div",null,[...t[0]||(t[0]=[l(`<p>好的，这是一份关于“可观测性-日志管理-日志收集”的详细学习笔记。笔记将遵循从宏观到微观的逻辑，并结合 Mermaid 图表进行说明。</p><hr><h2 id="可观测性、日志管理与日志收集学习笔记" tabindex="-1">可观测性、日志管理与日志收集学习笔记 <a class="header-anchor" href="#可观测性、日志管理与日志收集学习笔记" aria-label="Permalink to &quot;可观测性、日志管理与日志收集学习笔记&quot;">​</a></h2><h3 id="第一部分-核心概念" tabindex="-1">第一部分：核心概念 <a class="header-anchor" href="#第一部分-核心概念" aria-label="Permalink to &quot;第一部分：核心概念&quot;">​</a></h3><h4 id="_1-可观测性" tabindex="-1">1. 可观测性 <a class="header-anchor" href="#_1-可观测性" aria-label="Permalink to &quot;1. 可观测性&quot;">​</a></h4><ul><li><strong>定义</strong>：可观测性不仅仅是监控。它是指<strong>通过系统的外部输出来理解其内部状态的能力</strong>。一个系统可观测性越高，我们越能通过其产生的数据快速定位和诊断未知问题。</li><li><strong>三大支柱</strong>： <ol><li><strong>日志</strong>：系统在特定时间点发生的事件的离散记录。回答“<strong>发生了什么</strong>”。</li><li><strong>指标</strong>：随时间变化的、可聚合的数值数据。回答“<strong>系统表现如何</strong>”。</li><li><strong>追踪</strong>：单个请求在分布式系统中端到端的路径和性能。回答“<strong>请求经过了哪里，性能瓶颈在哪</strong>”。</li></ol></li></ul><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_140thh">graph TD</span></span>
<span class="line"><span class="__shiki_140thh">    A[可观测性] --&gt; B[三大支柱]</span></span>
<span class="line"><span class="__shiki_140thh">    B --&gt; C[日志]</span></span>
<span class="line"><span class="__shiki_140thh">    B --&gt; D[指标]</span></span>
<span class="line"><span class="__shiki_140thh">    B --&gt; E[追踪]</span></span>
<span class="line"><span class="__shiki_140thh">    </span></span>
<span class="line"><span class="__shiki_140thh">    C --&gt; C1[发生了什么&lt;br&gt;离散事件]</span></span>
<span class="line"><span class="__shiki_140thh">    D --&gt; D1[系统表现如何&lt;br&gt;聚合数据]</span></span>
<span class="line"><span class="__shiki_140thh">    E --&gt; E1[请求路径与瓶颈&lt;br&gt;分布式链路]</span></span></code></pre></div><h4 id="_2-日志管理" tabindex="-1">2. 日志管理 <a class="header-anchor" href="#_2-日志管理" aria-label="Permalink to &quot;2. 日志管理&quot;">​</a></h4><ul><li><strong>定义</strong>：一个涵盖日志从生成到最终处置的完整生命周期管理过程。</li><li><strong>目标</strong>：确保日志数据可用、可靠、安全，并能被高效地用于故障排查、安全审计和业务分析。</li><li><strong>生命周期</strong>： <ol><li><strong>生成与收集</strong></li><li><strong>传输与缓冲</strong></li><li><strong>处理与丰富</strong></li><li><strong>存储与索引</strong></li><li><strong>分析与可视化</strong></li><li><strong>归档与销毁</strong></li></ol></li></ul><h4 id="_3-日志收集" tabindex="-1">3. 日志收集 <a class="header-anchor" href="#_3-日志收集" aria-label="Permalink to &quot;3. 日志收集&quot;">​</a></h4><ul><li><strong>定义</strong>：日志管理生命周期的第一个关键环节，负责从各种来源（如应用程序、操作系统、网络设备等）可靠地获取日志数据，并将其发送到中央处理系统。</li><li><strong>核心挑战</strong>： <ul><li><strong>来源多样性</strong>：日志格式、输出位置（文件、标准输出、网络端口）各不相同。</li><li><strong>数据海量性</strong>：在微服务和云原生环境下，日志数据量巨大。</li><li><strong>可靠性</strong>：不能因为日志收集影响应用性能，也不能丢失日志。</li><li><strong>资源消耗</strong>：收集代理本身应尽可能轻量。</li></ul></li></ul><hr><h3 id="第二部分-日志收集详解" tabindex="-1">第二部分：日志收集详解 <a class="header-anchor" href="#第二部分-日志收集详解" aria-label="Permalink to &quot;第二部分：日志收集详解&quot;">​</a></h3><h4 id="_1-日志收集架构" tabindex="-1">1. 日志收集架构 <a class="header-anchor" href="#_1-日志收集架构" aria-label="Permalink to &quot;1. 日志收集架构&quot;">​</a></h4><p>一个典型的日志收集架构包含以下组件：</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_140thh">graph LR</span></span>
<span class="line"><span class="__shiki_140thh">    A[应用程序/系统] --&gt;|写入日志| B[日志源]</span></span>
<span class="line"><span class="__shiki_140thh">    B --&gt;|采集| C[收集代理]</span></span>
<span class="line"><span class="__shiki_140thh">    C --&gt;|转发| D[中央日志平台]</span></span>
<span class="line"><span class="__shiki_140thh">    D --&gt; E[处理/丰富]</span></span>
<span class="line"><span class="__shiki_140thh">    E --&gt; F[存储/索引]</span></span>
<span class="line"><span class="__shiki_140thh">    F --&gt; G[分析/可视化]</span></span>
<span class="line"><span class="__shiki_140thh">    </span></span>
<span class="line"><span class="__shiki_140thh">    subgraph 收集代理</span></span>
<span class="line"><span class="__shiki_140thh">        C --&gt; C1[本地缓冲]</span></span>
<span class="line"><span class="__shiki_140thh">    end</span></span>
<span class="line"><span class="__shiki_140thh">    </span></span>
<span class="line"><span class="__shiki_140thh">    subgraph 中央日志平台</span></span>
<span class="line"><span class="__shiki_140thh">        D --&gt; D1[消息队列&lt;br&gt;如Kafka]</span></span>
<span class="line"><span class="__shiki_140thh">    end</span></span></code></pre></div><h4 id="_2-关键组件与角色" tabindex="-1">2. 关键组件与角色 <a class="header-anchor" href="#_2-关键组件与角色" aria-label="Permalink to &quot;2. 关键组件与角色&quot;">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">组件</th><th style="text-align:left;">角色</th><th style="text-align:left;">常见示例</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>日志源</strong></td><td style="text-align:left;">产生日志的实体</td><td style="text-align:left;">应用程序（文件、<code>stdout</code>）、系统日志（<code>syslog</code>）、网络设备</td></tr><tr><td style="text-align:left;"><strong>收集代理</strong></td><td style="text-align:left;">在日志源端运行，负责采集、初步解析和转发日志</td><td style="text-align:left;">Fluentd, Logstash, Filebeat, Fluent Bit, Vector</td></tr><tr><td style="text-align:left;"><strong>消息队列/缓冲</strong></td><td style="text-align:left;">解耦收集代理与后端处理系统，应对流量高峰，保证数据不丢失</td><td style="text-align:left;">Apache Kafka, Redis, RabbitMQ</td></tr><tr><td style="text-align:left;"><strong>日志路由器/聚合器</strong></td><td style="text-align:left;">接收来自多个代理的日志，进行路由、过滤和聚合（可与代理合并）</td><td style="text-align:left;">Fluentd, Logstash</td></tr><tr><td style="text-align:left;"><strong>中央平台</strong></td><td style="text-align:left;">接收、处理、存储和索引日志数据的后端系统</td><td style="text-align:left;">Elasticsearch, Splunk, Loki, Graylog</td></tr></tbody></table><h4 id="_3-主流收集代理对比" tabindex="-1">3. 主流收集代理对比 <a class="header-anchor" href="#_3-主流收集代理对比" aria-label="Permalink to &quot;3. 主流收集代理对比&quot;">​</a></h4><table tabindex="0"><thead><tr><th style="text-align:left;">特性</th><th style="text-align:left;"><strong>Fluentd</strong></th><th style="text-align:left;"><strong>Logstash</strong></th><th style="text-align:left;"><strong>Filebeat</strong></th><th style="text-align:left;"><strong>Fluent Bit</strong></th><th style="text-align:left;"><strong>Vector</strong></th></tr></thead><tbody><tr><td style="text-align:left;"><strong>核心定位</strong></td><td style="text-align:left;">统一数据收集层</td><td style="text-align:left;">ETL引擎</td><td style="text-align:left;">轻量级日志转发器</td><td style="text-align:left;">轻量级Fluentd</td><td style="text-align:left;">高性能可观测性管道</td></tr><tr><td style="text-align:left;"><strong>语言</strong></td><td style="text-align:left;">Ruby + C</td><td style="text-align:left;">JRuby</td><td style="text-align:left;">Go</td><td style="text-align:left;">C</td><td style="text-align:left;">Rust</td></tr><tr><td style="text-align:left;"><strong>性能</strong></td><td style="text-align:left;">良好</td><td style="text-align:left;">较高资源消耗</td><td style="text-align:left;"><strong>极低</strong></td><td style="text-align:left;"><strong>极低</strong></td><td style="text-align:left;"><strong>极高</strong></td></tr><tr><td style="text-align:left;"><strong>资源占用</strong></td><td style="text-align:left;">中等</td><td style="text-align:left;">高</td><td style="text-align:left;"><strong>非常低</strong></td><td style="text-align:left;"><strong>极低</strong></td><td style="text-align:left;">低</td></tr><tr><td style="text-align:left;"><strong>配置灵活性</strong></td><td style="text-align:left;">高</td><td style="text-align:left;">非常高</td><td style="text-align:left;">中等</td><td style="text-align:left;">中等</td><td style="text-align:left;">高</td></tr><tr><td style="text-align:left;"><strong>云原生友好度</strong></td><td style="text-align:left;">高（CNCF项目）</td><td style="text-align:left;">中等</td><td style="text-align:left;">高（Elastic Stack）</td><td style="text-align:left;"><strong>非常高</strong>（CNCF项目）</td><td style="text-align:left;"><strong>非常高</strong></td></tr><tr><td style="text-align:left;"><strong>主要场景</strong></td><td style="text-align:left;">通用数据收集， K8s环境</td><td style="text-align:left;">ELK Stack， 复杂数据处理</td><td style="text-align:left;">ELK/EFK Stack， 轻量转发</td><td style="text-align:left;">容器、边缘设备</td><td style="text-align:left;">对性能要求极高的场景</td></tr></tbody></table><hr><h3 id="第四部分-实践流程与最佳实践" tabindex="-1">第四部分：实践流程与最佳实践 <a class="header-anchor" href="#第四部分-实践流程与最佳实践" aria-label="Permalink to &quot;第四部分：实践流程与最佳实践&quot;">​</a></h3><h4 id="_1-日志收集标准流程" tabindex="-1">1. 日志收集标准流程 <a class="header-anchor" href="#_1-日志收集标准流程" aria-label="Permalink to &quot;1. 日志收集标准流程&quot;">​</a></h4><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_140thh">sequenceDiagram</span></span>
<span class="line"><span class="__shiki_140thh">    participant A as 应用程序</span></span>
<span class="line"><span class="__shiki_140thh">    participant F as 日志文件/stdout</span></span>
<span class="line"><span class="__shiki_140thh">    participant C as 收集代理</span></span>
<span class="line"><span class="__shiki_140thh">    participant Q as 消息队列</span></span>
<span class="line"><span class="__shiki_140thh">    participant P as 处理平台</span></span>
<span class="line"><span class="__shiki_140thh">    participant S as 存储</span></span>
<span class="line"></span>
<span class="line"><span class="__shiki_140thh">    A-&gt;&gt;F: 写入日志</span></span>
<span class="line"><span class="__shiki_140thh">    loop 持续监控</span></span>
<span class="line"><span class="__shiki_140thh">        C-&gt;&gt;F: 采集/尾追新日志</span></span>
<span class="line"><span class="__shiki_140thh">    end</span></span>
<span class="line"><span class="__shiki_140thh">    C-&gt;&gt;C: 解析 &amp; 结构化 &amp; 过滤</span></span>
<span class="line"><span class="__shiki_140thh">    C-&gt;&gt;Q: 转发日志事件</span></span>
<span class="line"><span class="__shiki_140thh">    Note over Q: 缓冲 &amp; 解耦</span></span>
<span class="line"><span class="__shiki_140thh">    Q-&gt;&gt;P: 消费日志</span></span>
<span class="line"><span class="__shiki_140thh">    P-&gt;&gt;P: 进一步丰富 &amp; 索引</span></span>
<span class="line"><span class="__shiki_140thh">    P-&gt;&gt;S: 存储至后端</span></span></code></pre></div><h4 id="_2-最佳实践" tabindex="-1">2. 最佳实践 <a class="header-anchor" href="#_2-最佳实践" aria-label="Permalink to &quot;2. 最佳实践&quot;">​</a></h4><ol><li><p><strong>结构化日志</strong>：</p><ul><li>优先输出 JSON 格式的日志，而不是纯文本。这便于后续的解析和字段查询。</li><li><em>示例</em>： <code>{&quot;timestamp&quot;: &quot;2023-10-27T10:00:00Z&quot;, &quot;level&quot;: &quot;ERROR&quot;, &quot;message&quot;: &quot;Database connection failed&quot;, &quot;user_id&quot;: 12345}</code></li></ul></li><li><p><strong>配置合理的日志级别</strong>： 避免在生产环境大量输出 <code>DEBUG</code> 日志，减少不必要的开销。</p></li><li><p><strong>使用侧车模式</strong>： 在 Kubernetes 中，为每个 Pod 部署一个专用的日志收集代理容器（如 Fluent Bit），与业务容器共享日志卷。这是最推荐的模式。</p><div class="language-mermaid vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">mermaid</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span class="__shiki_140thh">graph TB</span></span>
<span class="line"><span class="__shiki_140thh">    subgraph Pod</span></span>
<span class="line"><span class="__shiki_140thh">        A[业务容器]</span></span>
<span class="line"><span class="__shiki_140thh">        F[日志收集容器&lt;br&gt;Fluent Bit]</span></span>
<span class="line"><span class="__shiki_140thh">        A -- 写入日志 --&gt; V[共享Volume]</span></span>
<span class="line"><span class="__shiki_140thh">        V -- 读取日志 --&gt; F</span></span>
<span class="line"><span class="__shiki_140thh">    end</span></span>
<span class="line"><span class="__shiki_140thh">    F --&gt; CentralLogging[中央日志平台]</span></span></code></pre></div></li><li><p><strong>解耦与缓冲</strong>： 务必在收集代理和后端处理系统之间使用 Kafka 等消息队列，以应对后端故障或流量激增。</p></li><li><p><strong>敏感信息处理</strong>： 在收集或处理阶段，使用插件对密码、密钥、身份证号等敏感信息进行脱敏。</p></li><li><p><strong>使用标签/元数据丰富日志</strong>： 在收集时为日志添加诸如 <code>pod_name</code>, <code>namespace</code>, <code>node_name</code>, <code>app_version</code> 等元数据，便于在分布式环境中定位问题。</p></li></ol><hr><h3 id="第五部分-现代架构与趋势" tabindex="-1">第五部分：现代架构与趋势 <a class="header-anchor" href="#第五部分-现代架构与趋势" aria-label="Permalink to &quot;第五部分：现代架构与趋势&quot;">​</a></h3><h4 id="_1-efk-stack-elasticsearch-fluentd-fluent-bit-kibana" tabindex="-1">1. EFK Stack（Elasticsearch + Fluentd/Fluent Bit + Kibana） <a class="header-anchor" href="#_1-efk-stack-elasticsearch-fluentd-fluent-bit-kibana" aria-label="Permalink to &quot;1. EFK Stack（Elasticsearch + Fluentd/Fluent Bit + Kibana）&quot;">​</a></h4><ul><li><strong>Fluentd/Fluent Bit</strong>： 负责收集和传输日志。</li><li><strong>Elasticsearch</strong>： 负责存储和索引日志，提供强大的搜索能力。</li><li><strong>Kibana</strong>： 负责日志的可视化、查询和分析。</li><li>这是目前最流行的开源日志管理解决方案之一。</li></ul><h4 id="_2-loki-stack-grafana-loki-promtail-grafana" tabindex="-1">2. Loki Stack（Grafana Loki + Promtail + Grafana） <a class="header-anchor" href="#_2-loki-stack-grafana-loki-promtail-grafana" aria-label="Permalink to &quot;2. Loki Stack（Grafana Loki + Promtail + Grafana）&quot;">​</a></h4><ul><li><strong>设计哲学</strong>： 只索引日志的元数据（标签），而不索引日志内容，存储压缩的日志内容。更简单、成本更低。</li><li><strong>Promtail</strong>： 负责收集日志并添加标签，然后发送给 Loki。</li><li><strong>Loki</strong>： 日志存储引擎。</li><li><strong>Grafana</strong>： 用于查询和可视化 Loki 中的日志，可以与指标和追踪在同一界面中展示。</li><li>特别适合与 Prometheus 指标和 Tempo/Grafana 追踪一起使用，实现统一的可观测性。</li></ul><h4 id="_3-无代理架构" tabindex="-1">3. 无代理架构 <a class="header-anchor" href="#_3-无代理架构" aria-label="Permalink to &quot;3. 无代理架构&quot;">​</a></h4><p>在某些 Serverless 或高度受限的环境中，应用程序可能直接将日志推送到一个中央化的服务（如云服务商的日志服务），而不在本地运行收集代理。</p><hr><h3 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h3><ul><li><strong>日志是可观测性的基石</strong>，它记录了离散事件，用于回答“发生了什么”。</li><li><strong>日志收集是日志管理的入口</strong>，其核心是可靠、高效地从各种来源获取数据。</li><li>选择合适的<strong>收集代理</strong>（如 Fluentd, Filebeat, Fluent Bit, Vector）是关键决策，需权衡性能、资源和功能。</li><li>一个健壮的收集架构必须考虑<strong>缓冲（Kafka）</strong> 和<strong>处理</strong>。</li><li>遵循<strong>最佳实践</strong>（结构化、侧车模式、解耦、脱敏）是保证日志系统有效性的前提。</li><li>现代日志系统（如 EFK 和 Loki）提供了完整的解决方案，选择取决于具体需求（如全文本搜索 vs. 成本效率）。</li></ul>`,37)])])}const _=s(e,[["render",i]]);export{c as __pageData,_ as default};
